use-reducer-todo-list.referenceSolution:
const todoReducer = (state, action) => {
  switch (action.type) {
    case 'ADD_TODO': {
      const id = state.reduce((max, t) => Math.max(max, t.id), 0) + 1;
      return [...state, { id, text: action.payload, done: false }];
    }
    case 'TOGGLE_TODO':
      return state.map((t) => (t.id === action.payload ? { ...t, done: !t.done } : t));
    case 'REMOVE_TODO':
      return state.filter((t) => t.id !== action.payload);
    default:
      return state;
  }
}

use-reducer-todo-list.referenceSolutionTs:
interface TodoItem {
  id: number;
  text: string;
  done: boolean;
}

type TodoAction =
  | { type: 'ADD_TODO'; payload: string }
  | { type: 'TOGGLE_TODO'; payload: number }
  | { type: 'REMOVE_TODO'; payload: number }
  | { type: string; payload?: unknown };

const todoReducer = (state: TodoItem[], action: TodoAction): TodoItem[] => {
  switch (action.type) {
    case 'ADD_TODO': {
      const id = state.reduce((max, t) => Math.max(max, t.id), 0) + 1;
      return [...state, { id, text: action.payload as string, done: false }];
    }
    case 'TOGGLE_TODO':
      return state.map((t) => (t.id === action.payload ? { ...t, done: !t.done } : t));
    case 'REMOVE_TODO':
      return state.filter((t) => t.id !== action.payload);
    default:
      return state;
  }
}

context-provider-consumer.promptSeed:
```ts
type Theme = 'light' | 'dark';

interface ThemeContextValue {
  theme: Theme;
  setTheme: (next: Theme) => void;
  toggle: () => void;
}

interface ThemeProviderProps {
  children?: React.ReactNode;
  defaultTheme?: Theme;
}
```

Implement a factory function for a React Theme Context:

### `createThemeContext(): { ThemeProvider: (props: ThemeProviderProps) => JSX.Element; useTheme: () => ThemeContextValue }`
- Creates an internal React context via `createContext(null)`.
- Returns an object containing `{ ThemeProvider, useTheme }`.

### `ThemeProvider({ children, defaultTheme = 'light' }: ThemeProviderProps): JSX.Element`
- Manages theme state (`'light' | 'dark'`) initialized to `defaultTheme` (defaults to `'light'`).
- Provides a context value object: `{ theme, setTheme, toggle }`.
  - `toggle()` flips between `'light'` and `'dark'`.
  - Memoizes callbacks and the context value object where appropriate.

### `useTheme(): ThemeContextValue`
- Custom hook that consumes the theme context via `useContext`.
- Returns `{ theme, setTheme, toggle }`.
- Throws an `Error` whose message mentions `'ThemeProvider'` when invoked outside of a `<ThemeProvider>`.

