context-provider-consumer.referenceSolution:
const createThemeContext = () => {
  const ThemeContext = createContext(null);

  const ThemeProvider = ({ children, defaultTheme = 'light' }) => {
    const [theme, setTheme] = useState(defaultTheme);
    const toggle = useCallback(() => setTheme((t) => (t === 'light' ? 'dark' : 'light')), []);
    const value = useMemo(() => ({ theme, setTheme, toggle }), [theme, toggle]);
    return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
  };

  const useTheme = () => {
    const ctx = useContext(ThemeContext);
    if (!ctx) throw new Error('useTheme must be used within a ThemeProvider');
    return ctx;
  };

  return { ThemeProvider, useTheme };
};

context-provider-consumer.referenceSolutionTs:
type Theme = 'light' | 'dark';

interface ThemeContextValue {
  theme: Theme;
  setTheme: (theme: Theme | ((prev: Theme) => Theme)) => void;
  toggle: () => void;
}

interface ThemeProviderProps {
  children?: React.ReactNode;
  defaultTheme?: Theme;
}

interface ThemeContextResult {
  ThemeProvider: (props: ThemeProviderProps) => JSX.Element;
  useTheme: () => ThemeContextValue;
}

const createThemeContext = (): ThemeContextResult => {
  const ThemeContext = createContext<ThemeContextValue | null>(null);

  const ThemeProvider = ({ children, defaultTheme = 'light' }: ThemeProviderProps): JSX.Element => {
    const [theme, setTheme] = useState<Theme>(defaultTheme);
    const toggle = useCallback(() => setTheme((t) => (t === 'light' ? 'dark' : 'light')), []);
    const value = useMemo<ThemeContextValue>(() => ({ theme, setTheme, toggle }), [theme, toggle]);
    return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
  };

  const useTheme = (): ThemeContextValue => {
    const ctx = useContext<ThemeContextValue | null>(ThemeContext);
    if (!ctx) throw new Error('useTheme must be used within a ThemeProvider');
    return ctx;
  };

  return { ThemeProvider, useTheme };
};

